"""Pure: Mermaid source generated by code from a validated graph, so it always parses and no label can
inject syntax: quotes, brackets, pipes, semicolons, hashes and angle brackets are replaced."""

from __future__ import annotations

import re

from dataset import Dataset
from graphspec import Graph, Node

MAX_MERMAID_LABEL = 40
_UNSAFE = re.compile(r"[\"\[\](){}<>|;#`]")
_SHAPES = {"step": ('["', '"]'), "decision": ('{"', '"}'), "start_end": ('(["', '"])'), "actor": ('(["', '"])')}


def safe(label: str, limit: int = MAX_MERMAID_LABEL) -> str:
    text = " ".join(_UNSAFE.sub(" ", (label or "").replace("\n", " ")).split())
    text = text.replace(":", " -") if text else "untitled"
    return text if len(text) <= limit else text[:limit - 1].rstrip() + "…"


def render(graph: Graph) -> str:
    if graph.kind == "sequence":
        return _sequence(graph)
    if graph.kind == "timeline":
        return _timeline(graph)
    if graph.kind == "mindmap":
        return _mindmap(graph)
    return _flow(graph)


def _node(node: Node) -> str:
    left, right = _SHAPES[node.shape]
    return f"{node.id}{left}{safe(node.label)}{right}"


def _flow(graph: Graph) -> str:
    direction = "TD" if graph.kind == "tree" else graph.direction
    lines = [f"flowchart {direction}"]
    grouped = {m for _, members in graph.groups for m in members}
    for k, (name, members) in enumerate(graph.groups, start=1):
        lines.append(f'  subgraph G{k}["{safe(name)}"]')
        lines += [f"    {_node(graph.node(m))}" for m in members]
        lines.append("  end")
    lines += [f"  {_node(n)}" for n in graph.nodes if n.id not in grouped]
    for edge in graph.edges:
        arrow = f'-->|"{safe(edge.label, 24)}"|' if edge.label else "-->"
        lines.append(f"  {edge.src} {arrow} {edge.dst}")
    return "\n".join(lines)


def _sequence(graph: Graph) -> str:
    lines = ["sequenceDiagram"]
    lines += [f"  participant {n.id} as {safe(n.label)}" for n in graph.nodes]
    lines += [f"  {e.src}->>{e.dst}: {safe(e.label or 'message', 60)}" for e in graph.edges]
    return "\n".join(lines)


def _timeline(graph: Graph) -> str:
    lines = ["timeline", f"  title {safe(graph.title, 60)}"]
    for node in graph.nodes:
        when, _, what = node.label.partition(":")
        lines.append(f"  {safe(when)} : {safe(what)}" if what.strip() else f"  {safe(node.label)}")
    return "\n".join(lines)


def _mindmap(graph: Graph) -> str:
    children: dict[str, list[str]] = {}
    has_parent = {e.dst for e in graph.edges}
    for edge in graph.edges:
        children.setdefault(edge.src, []).append(edge.dst)
    roots = [n.id for n in graph.nodes if n.id not in has_parent] or [graph.nodes[0].id]
    lines, seen = ["mindmap", f"  root(({safe(graph.title)}))"], set()

    def walk(node_id: str, depth: int) -> None:
        if node_id in seen:
            return
        seen.add(node_id)
        lines.append("  " * depth + safe(graph.node(node_id).label))
        for child in children.get(node_id, []):
            walk(child, depth + 1)

    for root in roots:
        walk(root, 2)
    return "\n".join(lines)


def pie(ds: Dataset, title: str) -> str:
    lines = [f"pie showData title {safe(title, 60)}"]
    lines += [f'  "{safe(label)}" : {value:g}' for label, value in zip(ds.labels, ds.values[0], strict=True)]
    return "\n".join(lines)
